REPLACE INTO `quest_template_locale` SET `ID`='1903512', `Locale`='zhCN', `Title`='升天之路：收藏与主城', `Details`='打开角色成长菜单，然后点击外观页签。\\n搜索回归卷轴，或按已学过滤，点击卷轴并按下交纳物品！', `Objectives`='打开角色成长菜单，然后点击外观页签。\\n搜索回归卷轴，或按已学过滤，点击卷轴并按下交纳物品！', `EndText`='', `CompletedText`='在升天之路中领取奖励。', `ObjectiveText1`='', `ObjectiveText2`='', `ObjectiveText3`='', `ObjectiveText4`='';
REPLACE INTO `quest_template_locale` SET `ID`='1903513', `Locale`='zhCN', `Title`='升天之路：激活秘法卷轴', `Details`='秘法附魔卷轴可以通过击败敌人、在世界各地探索发现，或者与其他玩家交易获得。    一旦获得，前往秘法附魔祭坛，把秘法卷轴刻入以获得它的力量！主城中通常能见到被召唤出来的秘法附魔祭坛，你也可以到世界各地去寻访一座。它们的位置标注在世界地图上。    秘法附魔是解锁英雄力量的关键。寻找能够强化你的法术、或解锁全新流派的秘法附魔，来提升你的实力。', `Objectives`='- 通过击败敌人或与其他玩家交易，获得一张秘法附魔卷轴。  - 与主城或世界中找到的秘法附魔祭坛互动，选择卷轴附魔页签。  - 激活一张秘法卷轴，并把它刻入一个生效附魔槽位。', `EndText`='', `CompletedText`='回到委托板。', `ObjectiveText1`='', `ObjectiveText2`='', `ObjectiveText3`='', `ObjectiveText4`='';
