REPLACE INTO `quest_template_locale` SET `ID`='4420439', `Locale`='zhCN', `Title`='升天之路：新手骑术', `Details`='新兵，你好！$B$B有些教官固守老一套，把初出茅庐的冒险者打发去翻山越岭，走上好像四十里路全是上坡的苦差事。在这儿没必要那样。花一点微不足道的费用，你就能学会新手骑术，获得你的第一匹坐骑和稳定的 40% 速度加成。$B$B旅途中有足够多的事让你忙活：发现宝藏、磨炼技巧、试炼胆色。世界正在等你，没道理拖你的后腿。$B$B在这里，我们宁愿看你骑马，也不愿看你磨烂靴子。等你技艺更熟、积蓄更足，可以回来找骑术训练师提升骑术等级，让坐骑跑得更快。', `Objectives`='学会骑术并领取你的第一匹坐骑。', `EndText`='', `CompletedText`='回到骑术训练师那里。', `ObjectiveText1`='已学会新手骑术', `ObjectiveText2`='', `ObjectiveText3`='', `ObjectiveText4`='';
